// Structural size of types, for the sampler's size penalties. Measured on the
// model rather than on rendered text so names cost nothing, and available
// before anything is rendered or compiled. Every measure is a fold over
// `children`, so adding a `Ty` variant is decided once, there.

/// Nodes in the type tree. An alias reference counts as one node; its
/// declaration is measured separately if at all.
function size(ty: Ty) -> int throws never {
    1
        + children(ty).reduce(
            (acc, c) -> {
                acc + size(c)
            },
            0,
        )
}

/// Nesting depth: how many constructors sit above the deepest leaf.
function depth(ty: Ty) -> int throws never {
    1
        + children(ty).reduce(
            (acc, c) -> {
                acc.max(depth(c))
            },
            0,
        )
}

/// The widest union anywhere in the type, or zero without one.
function union_width(ty: Ty) -> int throws never {
    let own = match (ty) {
        let u: Union => u.members().length(),
        Prim | Never | Top | Lit | EnumLit | Array | Map | Fn | Class | Enum | Iface | Alias | Var => {
            0
        },
    };
    children(ty).reduce(
        (acc, c) -> {
            acc.max(union_width(c))
        },
        own,
    )
}

// Naive models: a plausible wrong intuition, expressed as a sparse set of
// overrides on rules. A model agrees with the spec wherever it says nothing,
// so it is never a second type system, only a list of the places one
// intuition parts company with BAML. The bank defines the models; the
// derivation replay in `relation.baml` consults them.

class Model {
    id: string,
    /// One paragraph for the grader, in the second person: what a learner
    /// running this model believes.
    description: string,
    /// For a rule that asserts a pair's relation: what the model believes
    /// about that pair, or `null` to defer to the spec for these types.
    believes: map<string, (Ty, Ty) -> Relation? throws never>,
    /// For a rule that transforms a relation: the model's transfer instead.
    transfers: map<string, (Knowledge) -> Knowledge throws never>,
}

// The type model the generators build cases from.
//
// This is tested material, not the compiler: it exists so a generator can
// construct types and declarations as data and hand the compiler their
// rendering. Nothing here decides subtyping or equivalence. `render.baml`
// spells a `Ty` as source, and the conformance suite checks that spelling
// against the compiler's own reading of it.
//
// Every variant that names a declaration carries the declaration itself, so a
// rendered case can never reference a class, enum, interface, or alias that
// it does not also declare. Shapes the language cannot spell are kept
// unrepresentable where the type system allows (a union has at least two
// members, a map's key is `string`, positional parameters precede named
// ones) and rejected by the constructor where it does not (generic arity,
// enum variants).

/// The builtin concrete types.
enum PrimKind {
    Int,
    Float,
    Bool,
    String,
    Bigint,
    Null,
    Uint8Array,
}

// What the sampler scores a case by. Names are the contract with
// `weights.baml`; the engine only sees numbers.

/// The features of a case: how many distinct rules its explanation uses
/// (without the flow rule every flow item ends with), how many times its
/// derivation flips a subtype into a supertype, the structural size of the
/// types it renders, and the models it traps.
function features_of(
    trace: root.engine.Claim[],
    flips: int,
    tys: root.algebra.Ty[],
    traps: string[],
) -> map<string, float> throws never {
    let none: string[] = [];
    let own = trace
        .map((claim) -> {
            claim.rule.name
        })
        .filter((name) -> {
            !is_site_rule(name)
        })
        .reduce(
            (acc, name) -> {
                if (acc.includes(name)) {
                    acc
                } else {
                    acc.concat([name])
                }
            },
            none,
        );
    let size = tys.reduce(
        (acc, ty) -> {
            acc + root.algebra.size(ty)
        },
        0,
    );
    let depth = tys.reduce(
        (acc, ty) -> {
            acc.max(root.algebra.depth(ty))
        },
        0,
    );
    let width = tys.reduce(
        (acc, ty) -> {
            acc.max(root.algebra.union_width(ty))
        },
        0,
    );
    let features: map<string, float> = {
        "rules": own.length() * 1.0,
        "flips": flips * 1.0,
        "size": size * 1.0,
        "depth": depth * 1.0,
        "width": width * 1.0,
        "traps": traps.length() * 1.0,
        "boring": if (own.length() == 1 && traps.length() == 0) {
            1.0
        } else {
            0.0
        },
    };
    // A map literal cannot take a computed key, so the per-model flags are
    // set on the fresh map before it is returned.
    for (let model in traps) {
        features.set(`trap:${model}`, 1.0);
    }
    features
}

// The naive models: intuitions a learner might arrive with, each a sparse
// list of the rules where it disagrees with the spec. A case is a trap for a
// model when replaying its derivation under the model flips the verdict.
//
// A model is trapped only in the directions it is wrong in. One that accepts
// less than the spec (`spelling`) is trapped by compiling cases alone, one
// that accepts more (`typescript`) by rejected cases alone, and one that
// gets a variance backwards (`covariant`) by both.

function is_numeric(ty: root.algebra.Ty) -> bool throws never {
    match (ty) {
        let p: root.algebra.Prim => match (p.kind) {
            root.algebra.PrimKind.Int => true,
            root.algebra.PrimKind.Float => true,
            root.algebra.PrimKind.Bool => false,
            root.algebra.PrimKind.String => false,
            root.algebra.PrimKind.Bigint => false,
            root.algebra.PrimKind.Null => false,
            root.algebra.PrimKind.Uint8Array => false,
        },
        root.algebra.Never => false,
        root.algebra.Top => false,
        root.algebra.Lit => false,
        root.algebra.EnumLit => false,
        root.algebra.Union => false,
        root.algebra.Array => false,
        root.algebra.Map => false,
        root.algebra.Fn => false,
        root.algebra.Class => false,
        root.algebra.Enum => false,
        root.algebra.Iface => false,
        root.algebra.Alias => false,
        root.algebra.Var => false,
    }
}

function positional_arity(ty: root.algebra.Ty) -> int? throws never {
    match (ty) {
        let f: root.algebra.Fn => f.positional.length(),
        root.algebra.Prim => null,
        root.algebra.Never => null,
        root.algebra.Top => null,
        root.algebra.Lit => null,
        root.algebra.EnumLit => null,
        root.algebra.Union => null,
        root.algebra.Array => null,
        root.algebra.Map => null,
        root.algebra.Class => null,
        root.algebra.Enum => null,
        root.algebra.Iface => null,
        root.algebra.Alias => null,
        root.algebra.Var => null,
    }
}

// ─── constant beliefs ────────────────────────────────────────────────────────

// Cosmetic name pools. Names never change a verdict; they exist so a learner
// cannot recognise a case by its identifiers. The conformance suite compiles
// every pool entry in each position it is used in, so a keyword or a stdlib
// collision cannot enter a pool unnoticed.

function type_names() -> string[] throws never {
    ["Widget", "Ticket", "Parcel", "Beacon", "Ledger", "Orbit", "Kettle", "Harbor"]
}

// How high each rule reaches: the most type-system rules a case can hold when
// that rule is its conclusion. Derived from what the bank generates rather
// than declared beside each rule, so it cannot drift from the facts.

/// A rule's order, over the first `seeds` seeds of every item a sitting can
/// serve. Only verified items count, and only rules they conclude are
/// listed: a rule that reaches a learner solely through an item the compiler
/// disagrees with is not one a learner can be asked about, so it has no
/// place in what we expect them to master.
function rule_orders(seeds: int) -> root.engine.RuleOrder[] throws never {
    let servable = items().filter((item) -> {
        item.status() is root.engine.Verified
    });
    let traces = servable.flat_map((item) -> {
        let id = item.id();
        baml.iter.Range.new(0, seeds)
            .filter_map((i) -> {
                let candidate = root.engine.generate(item, root.engine.seed_for(id, i))
                    ?? return null;
                // The claims the answer TURNS ON, which is what the learner
                // is credited with when they get the case right. Measuring
                // the whole trace instead would set an order no sitting can
                // reach, and a rule whose order cannot be reached can never
                // be mastered and never stops being shaky.
                let own: string[] = root.engine.rules_of(candidate.case).filter((name) -> {
                    !is_site_rule(name)
                });
                own
            })
            .collect()
    });
    rules().filter_map((rule) -> {
        if (is_site_rule(rule.name)) {
            return null;
        }
        let orders = traces.filter_map((trace) -> {
            if (trace.at(-1) == rule.name) {
                trace.length()
            } else {
                null
            }
        });
        let sorted = orders.sort_by_key((n) -> {
            n
        });
        let highest = sorted.at(-1)
            ?? return null;
        let lowest = sorted.at(0)
            ?? return null;
        root.engine.RuleOrder { rule: rule.name, lowest, highest }
    })
}

// Every item in the bank, in one place. The conformance suite checks by
// reflection that every fact generator in this package is registered in
// `facts()`, and every fact becomes an item here.

// The default weight table: hand-set until a learner profile supplies one.
// Positive weights reward interest; size features carry a negative weight
// behind a hinge, so small cases are free and large ones pay quadratically
// until a hard cap rejects them.
//
// `boring` (a single rule every model agrees with) is a soft penalty, not a
// gate. Small rejected cases are mostly boring under today's models, so a
// gate would leave the session unable to balance the verdict among small
// cases; a learner profile can also want these as axiom drills.

function weight(weight: float) -> root.engine.Weight throws never {
    root.engine.Weight { weight: weight, hinge: null }
}

// The real BAML formatter, compiled to WebAssembly on its own.
//
// Cases are generated as text, and a learner should be reading them laid out
// the way this project lays out every other program: the question is what the
// code means, not how it is spaced. Running the formatter rather than
// generating already-formatted text is what keeps the generator from having
// to follow the formatter's rules as they change.

import init, { format } from '@quiz/fmt';

let started: Promise<unknown> | undefined;

/** Instantiate the formatter. Safe to call more than once. */
export function loadFormatter(): Promise<unknown> {
  const already = started;
  if (already !== undefined) {
    return already;
  }
  const starting = init();
  started = starting;
  return starting;
}

/**
 * `source`, laid out as `baml fmt` lays it out.
 *
 * Source that does not parse comes back unchanged from the formatter itself.
 * A throw means source that *did* parse could not be laid out, which is a
 * defect in the formatter; the learner is better served by the unformatted
 * program than by an empty screen, so it is reported and the original stands.
 */
export function formatSource(source: string): string {
  try {
    return format(source);
  } catch (error) {
    console.error('the formatter failed on a generated case', error);
    return source;
  }
}

// The save slots, as a game shows them.

import { useState } from 'react';
import type { Save, Slot } from './saves';

export function Home({
  slots,
  ready,
  onNew,
  onResume,
  onExport,
  onReset,
}: {
  slots: Slot[];
  /** Whether the formatter has loaded; every case is laid out by it. */
  ready: boolean;
  onNew: (slot: number) => void;
  onResume: (slot: number, save: Save) => void;
  onExport: (save: Save) => void;
  onReset: (slot: number) => void;
}) {
  const cards = slots.map((held, slot) => ({ held, slot }));
  return (
    <section className="home">
      <p className="blurb">
        A sitting is saved after every answer, so leave and come back whenever.
        {!ready && ' Loading the formatter…'}
      </p>
      {cards.map((card) => (
        <SlotCard
          held={card.held}
          key={card.slot}
          onExport={onExport}
          onNew={onNew}
          onReset={onReset}
          onResume={onResume}
          ready={ready}
          slot={card.slot}
        />
      ))}
    </section>
  );
}

// The grader, from the page's side: the learner's keys and chosen model,
// kept in this browser and nowhere else, and one call per judgement.
//
// A key goes into exactly one request, to the provider that issued it. The
// site is static and has no server of its own, so there is nothing of ours
// for a key to reach; storing them here rather than asking every time is a
// convenience the learner can undo by clearing the field.
//
// Keys are held one per provider, because that is what they belong to: a
// learner with an Anthropic key and an OpenAI key can move between models
// without pasting either again, and a key can never be sent to the provider
// that did not issue it.
//
// They live in the tab rather than in the browser. Storage is scoped to an
// origin and not to a path, and this site shares its origin with every other
// page the organisation publishes there, so a key left in local storage is
// readable by all of them for as long as it sits there.

import { engine } from '@quiz/sdk';
import type { Revealed } from './quiz';
import { keyStoreOf } from './saves';

export type Grade = engine.Grade;

/**
 * What came of asking: a grade with the mark it amounts to, or why there is
 * none. The engine hands its failures back as values rather than throwing
 * them, and the two outcomes are told apart here, so nothing above this file
 * has to know which of the union it is holding.
 */
export type Judgement =
  | { kind: 'grade'; grade: Grade; mark: string }
  | { kind: 'failed'; why: string };

